/* Counts calls per function address; dumps them at exit. */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define SLOTS 65536
static void *keys[SLOTS];
static unsigned long counts[SLOTS];

__attribute__((no_instrument_function)) void __cyg_profile_func_enter(void *fn, void *site) {
  (void)site;
  uintptr_t h = ((uintptr_t)fn >> 2) & (SLOTS - 1);
  while (keys[h] && keys[h] != fn) h = (h + 1) & (SLOTS - 1);
  keys[h] = fn;
  counts[h]++;
}

__attribute__((no_instrument_function)) void __cyg_profile_func_exit(void *fn, void *site) {
  (void)fn;
  (void)site;
}

extern int main(int, char **);

