TGL_HOT void gl_draw_triangle(GLVertex* p0, GLVertex* p1, GLVertex* p2) {
	GLPROF_SCOPE(GLPROF_TRIANGLE);
	GLContext* c = gl_get_context();
	GLint co, cc[3], front;

	cc[0] = p0->clip_code;
	cc[1] = p1->clip_code;
	cc[2] = p2->clip_code;

	co = cc[0] | cc[1] | cc[2];

	/* we handle the non clipped case here to go faster */
	if (co == 0) {
		GLfloat norm;
		norm = (GLfloat)(p1->zp.x - p0->zp.x) * (GLfloat)(p2->zp.y - p0->zp.y) - (GLfloat)(p2->zp.x - p0->zp.x) * (GLfloat)(p1->zp.y - p0->zp.y);

		if (norm == 0) 
			return;

		front = norm < 0.0f;
		front = front ^ c->current_front_face; 

		/* back face culling */
		if (c->cull_face_enabled) {
			/* most used case first */
			if (c->current_cull_face == GL_BACK) {
				if (front == 0)
					return;
				{ glshim_note_triangle(p0, p1, p2); c->draw_triangle_front(p0, p1, p2); }
			} else if (c->current_cull_face == GL_FRONT) {
				if (front != 0)
					return;
				{ glshim_note_triangle(p0, p1, p2); c->draw_triangle_back(p0, p1, p2); }
			} else {
				return;
			}
		} else {
			/* no culling */
			if (front) {
				{ glshim_note_triangle(p0, p1, p2); c->draw_triangle_front(p0, p1, p2); }
			} else {
				{ glshim_note_triangle(p0, p1, p2); c->draw_triangle_back(p0, p1, p2); }
			}
		}
	} else {
		/* GLint c_and = cc[0] & cc[1] & cc[2];*/
		if ((cc[0] & cc[1] & cc[2]) == 0) { /* Don't draw a triangle with no points*/
			gl_draw_triangle_clip(p0, p1, p2, 0);
		}
	}
}

