void gl_enable_disable_light(GLint light, GLint v) {
	GLContext* c = gl_get_context();
	GLLight* l = &c->lights[light];
	if (v && !l->enabled) {
		l->enabled = 1;
		l->next = c->first_light;
		c->first_light = l;
		l->prev = NULL;
	} else if (!v && l->enabled) {
		l->enabled = 0;
		if (l->prev == NULL)
			c->first_light = l->next;
		else
			l->prev->next = l->next;
		if (l->next != NULL)
			l->next->prev = l->prev;
	}
}


