anchor = """void setup() {
  auto cfg = M5.config();"""
bench = """#ifdef GL_PROFILE
/* Issue #43: cycles per 16-bit read-modify-write in PSRAM, walking along a
 * row (sequential) and down a column (each access a new cache line, as a
 * small triangle's rows are), and in internal RAM. Each pass runs twice, so
 * the XOR leaves the buffer as it was. */
static uint32_t memWalk(volatile uint16_t *buf, int count, int stride) {
  uint32_t start = glshim_prof_now();
  for (int pass = 0; pass < 2; pass++)
    for (int i = 0; i < count; i++) buf[(size_t)i * stride] ^= 1;
  return (glshim_prof_now() - start) / (2u * count);
}

static void memBench(uint16_t *psram) {
  const int rows = kSize;
  uint32_t seq = memWalk(psram, rows * kSize, 1);
  uint32_t col = memWalk(psram, rows, kSize);
  uint32_t colRead = 0;
  {
    volatile uint16_t *b = psram;
    uint32_t sum = 0, start = glshim_prof_now();
    for (int x = 0; x < 32; x++)
      for (int y = 0; y < rows; y++) sum += b[(size_t)y * kSize + x * 16];
    colRead = (glshim_prof_now() - start) / (32u * rows);
    (void)sum;
  }
  uint16_t *internal = (uint16_t *)heap_caps_malloc(16384, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
  uint32_t inner = internal ? memWalk(internal, 8192, 1) : 0;
  free(internal);
  Serial.printf("membench psram_seq=%u psram_col_rmw=%u psram_col_read=%u internal=%u cycles\\n",
                (unsigned)seq, (unsigned)col, (unsigned)colRead, (unsigned)inner);
}
#endif

"""
assert t.count(anchor) == 1
t = t.replace(anchor, bench + anchor)
a2 = """#if defined(GL_PROFILE) || defined(PSRAM_AUTOLOAD)
  cacheAutoload(canvas.px);
#endif
"""
assert t.count(a2) == 1
t = t.replace(a2, a2 + """#ifdef GL_PROFILE
  memBench(canvas.px);
#endif
""")
p.write_text(t)
EOF
grep -n 'kSize =' firmware/src/main.cpp | head -2; grep -n 'uint16_t \*px\|px;' firmware/src/core/canvas.h

